sys_variable_value.value:
(function execute(inputs, outputs) {

    var groupId = inputs.assignment_group.getUniqueValue();
    var selectedAgent = '';
    var minimumWorkload = -1;

    var member = new GlideRecord('sys_user_grmember');
    member.addQuery('group', groupId);
    member.addQuery('user.active', true);
    member.query();

    while (member.next()) {

        var userId = member.user.toString();

        var workload = new GlideAggregate('x_snc_unified_hr_0_hr_case');
        workload.addQuery('assigned_to', userId);

        var statusQuery = workload.addQuery('status', 'open');
        statusQuery.addOrCondition('status', 'in_progress');

        workload.addAggregate('COUNT');
        workload.query();

        var count = 0;

        if (workload.next()) {
            count = parseInt(workload.getAggregate('COUNT'), 10) || 0;
        }

        if (minimumWorkload === -1 || count < minimumWorkload) {
            minimumWorkload = count;
            selectedAgent = userId;
        }
    }

    outputs.selected_agent = selectedAgent;
    outputs.workload_count =
        minimumWorkload === -1 ? 0 : minimumWorkload;

})(inputs, outputs);

